 {code:'CL',tint:'bg-cyan-400/15 text-cyan-300',name:'Cleaning & Facility Management',tags:'cleaning facility hygiene',prospects:['Offices','Hotels','Schools','Hospitals','Shopping malls','Factories','Churches','Government institutions','NGOs','Apartments','Property managers'],opps:['Office cleaning contracts','Hotel contracts','Facility-management contracts','Government tenders','NGO procurement']},
 {code:'SE',tint:'bg-slate-400/15 text-slate-300',name:'Security',tags:'security guard cctv',prospects:['Banks','Hotels','Schools','Hospitals','Factories','Warehouses','Construction companies','Shopping centres','Offices','NGOs','Residential estates'],opps:['Security tenders','Guarding contracts','CCTV projects','Access-control projects','Facility contracts']},
 {code:'CA',tint:'bg-orange-400/15 text-orange-300',name:'Catering & Food Services',tags:'catering food restaurant events',prospects:['Corporates','NGOs','Schools','Universities','Hospitals','Hotels','Event companies','Churches','Government agencies'],opps:['Corporate catering','Event catering','Conference catering','NGO workshop catering','School meals','Government events']},
 {code:'PR',tint:'bg-violet-400/15 text-violet-300',name:'Printing & Branding',tags:'printing branding design signage',prospects:['Schools','NGOs','Corporates','Government agencies','Churches','Hotels','Events companies','Publishers','Ad agencies'],opps:['Annual reports','Brochures','Banners','Books','Stationery','Merchandise','Event materials']},
 {code:'FU',tint:'bg-yellow-400/15 text-yellow-300',name:'Office Furniture',tags:'furniture office interior',prospects:['Companies','Schools','Hospitals','Hotels','NGOs','Government institutions','Banks','Offices','Co-working spaces','Property developers'],opps:['Office furnishing','School furniture','Hospital furniture','Hotel furniture','Government procurement','NGO procurement']},
 {code:'AC',tint:'bg-teal-400/15 text-teal-300',name:'Accounting & Professional Services',tags:'accounting audit tax finance',prospects:['SMEs','NGOs','Schools','Churches','SACCOs','Startups','Companies','Cooperatives','Associations'],opps:['Audit contracts','Accounting contracts','Bookkeeping','Tax consultancy','Payroll','Financial reporting']},
